import * as React from "react"
import { NavLink, useNavigate } from "react-router-dom"
// removed ChevronDown import
import { cn } from "@/lib/utils"
import { AiComplianceMark } from "@/components/brand/AiComplianceMark"
import { apiFetch, authApi, documentsApi } from "@/lib/api"

export type SidebarProps = {
  collapsed?: boolean
}

type SidebarLink = {
  label: string
  to: string
  icon?: React.ReactNode
  /** Roles that may see this item. Undefined/empty = visible to all authenticated users. */
  roles?: string[]
}

const ICON_WRAPPER = "flex h-5 w-5 shrink-0 items-center justify-center [&>svg]:h-5 [&>svg]:w-5"

function Section({
  title,
  children,
}: {
  title: string
  children: React.ReactNode
}) {
  return (
    <div className="flex w-[235px] flex-col gap-2.5">
      <div
        className="flex h-5 w-[235px] items-center px-3 py-0 text-sm font-normal leading-5 text-muted-foreground"
        style={{ fontFamily: "Inter, sans-serif" }}
      >
        {title}
      </div>
      <div className="flex flex-col gap-2.5">{children}</div>
    </div>
  )
}

function SidebarItem({ link }: { link: SidebarLink }) {
  return (
    <NavLink
      to={link.to}
      className={({ isActive }) =>
        cn(
          "relative flex h-7 w-[235px] items-center rounded-lg pr-3 text-sm font-normal leading-5 transition-colors",
          "hover:bg-accent",
          isActive
            ? "bg-[#174199] text-white hover:bg-[#1F4ED8]"
            : "text-foreground"
        )
      }
      style={{ fontFamily: "Inter, sans-serif" }}
      end
      title={link.label}
    >
      {({ isActive }) => (
        <>
          {isActive && (
            <span
              className="absolute left-0 top-1/2 h-5 w-1 -translate-y-1/2 rounded-full bg-[#5BC0EB]"
              aria-hidden
            />
          )}
          <span className="flex flex-1 items-center gap-[0.55rem] pl-[25px]">
            {link.icon ? (
              <span className={ICON_WRAPPER}>{link.icon}</span>
            ) : null}
            <span className="truncate">{link.label}</span>
          </span>
        </>
      )}
    </NavLink>
  )
}

export function resolveTenantNavPath(orgSlug: string | null, to: string): string {
  if (!orgSlug) return to
  const enc = encodeURIComponent(orgSlug)
  const prefix = `/orgs/${enc}`
  if (to === "/dashboard/default") return `${prefix}/dashboard/default`
  if (
    to === "/validate-documents" ||
    to === "/upload-document" ||
    to === "/published-documents" ||
    to === "/audit-trail" ||
    to === "/social-media" ||
    to === "/social-media-settings"
  ) {
    return `${prefix}${to}`
  }
  return to
}

