// eslint-disable-next-line @typescript-eslint/no-unused-vars
export function Sidebar(_props: SidebarProps = {}) {
  const navigate = useNavigate()
  const [currentUser, setCurrentUser] = React.useState<{ name: string; initial: string }>({
    name: "Loading...",
    initial: "?",
  })
  const [userRoles, setUserRoles] = React.useState<string[]>([])
  const [orgSlug, setOrgSlug] = React.useState<string | null>(null)
  const [isProfileMenuOpen, setIsProfileMenuOpen] = React.useState(false)
  const profileMenuRef = React.useRef<HTMLDivElement | null>(null)

  React.useEffect(() => {
    documentsApi
      .getUserInfo()
      .then((me: any) => {
        const name = me?.full_name || me?.email || "User"
        setCurrentUser({ name, initial: name.charAt(0).toUpperCase() })
        if (Array.isArray(me?.roles)) {
          setUserRoles(me.roles.map((r: unknown) => String(r)))
        }
        const slug = me?.organization?.slug
        setOrgSlug(typeof slug === "string" && slug.trim() ? slug.trim() : null)
      })
      .catch(() => {})
  }, [])

  React.useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
        setIsProfileMenuOpen(false)
      }
    }

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsProfileMenuOpen(false)
      }
    }

    document.addEventListener("mousedown", handleClickOutside)
    document.addEventListener("keydown", handleEscape)

    return () => {
      document.removeEventListener("mousedown", handleClickOutside)
      document.removeEventListener("keydown", handleEscape)
    }
  }, [])

  const visibleMenuItems = React.useMemo(() => {
    return MENU_ITEMS.filter((link) => {
      if (!link.roles || link.roles.length === 0) return true
      return link.roles.some((r) => userRoles.includes(r))
    }).map((link) => ({ ...link, to: resolveTenantNavPath(orgSlug, link.to) }))
  }, [userRoles, orgSlug])

  const handleLogout = async () => {
    setIsProfileMenuOpen(false)
    // Cookie is httpOnly so the server must clear it.
    await authApi.logout().catch(() => undefined)
    navigate("/login")
  }

  const handleOpenProfile = () => {
    setIsProfileMenuOpen(false)
    navigate("/user-profile")
  }

  return (
    <aside className="flex h-screen w-[280px] flex-col border-r bg-card">

    {/* Logo */}
    <div className="pt-5 pl-6 pb-6">
      <AiComplianceMark />
    </div>
  
    {/* Menu: 15px margin from left */}
    <nav className="flex-1 ml-[15px] flex w-[235px] flex-col gap-2.5">
      <Section title="ComplyCore">
        {visibleMenuItems.map((link) => (
          <SidebarItem key={link.to} link={link} />
        ))}
      </Section>
    </nav>
  
    {/* Footer - full width, no bottom margin */}
    <footer className="mt-auto flex w-full flex-col">
      {/* User Profile Container: full width per Figma (279px), 76px height */}
      <div ref={profileMenuRef} className="relative flex h-[76px] w-full shrink-0 items-center pl-[37px]">
        {isProfileMenuOpen ? (
          <div className="absolute bottom-[68px] left-[37px] z-20 w-[220px] rounded-lg border bg-card p-1 shadow-lg">
            <button
              type="button"
              onClick={handleOpenProfile}
              className="flex h-9 w-full items-center gap-2 rounded-md px-3 text-left text-sm text-foreground hover:bg-accent"
            >
              <span className={ICON_WRAPPER}>
                <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M10 10.625C12.0711 10.625 13.75 8.94607 13.75 6.875C13.75 4.80393 12.0711 3.125 10 3.125C7.92893 3.125 6.25 4.80393 6.25 6.875C6.25 8.94607 7.92893 10.625 10 10.625Z" fill="currentColor" fillOpacity="0.4"/>
                  <path d="M10 11.875C6.72125 11.875 4.06187 14.5344 4.06187 17.8131C4.06187 18.1582 4.34169 18.4381 4.68687 18.4381H15.3131C15.6582 18.4381 15.9381 18.1582 15.9381 17.8131C15.9381 14.5344 13.2787 11.875 10 11.875Z" fill="currentColor"/>
                </svg>
              </span>
              Profile
            </button>
            <button
              type="button"
              onClick={handleLogout}
              className="flex h-9 w-full items-center gap-2 rounded-md px-3 text-left text-sm text-foreground hover:bg-accent"
            >
              <span className={ICON_WRAPPER}>
                <img src="/sidebar-icons/logoutIcon.svg" alt="" className="h-5 w-5" />
              </span>
              Logout
            </button>
          </div>
        ) : null}
        <button
          type="button"
          onClick={() => setIsProfileMenuOpen((prev) => !prev)}
          className="flex h-[30px] items-center gap-2 rounded-lg px-2 py-0.5 hover:bg-accent"
          title="Open Profile Menu"
          aria-haspopup="menu"
          aria-expanded={isProfileMenuOpen}
        >
          <div className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-muted text-xs font-semibold text-foreground">
            {currentUser.initial}
          </div>
          <span className="truncate text-sm text-foreground">{currentUser.name}</span>
          <span className={cn("transition-transform", isProfileMenuOpen ? "rotate-180" : "")} aria-hidden>
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M4 6L8 10L12 6" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </span>
        </button>
      </div>

      
    </footer>
  
  </aside>
  )
}